import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.RycU2wFZ.js";const p=JSON.parse('{"title":"A Neutral Guide to the Agent Payment Ecosystem","description":"","frontmatter":{},"headers":[],"relativePath":"learn/02-agent-payments/ecosystem-landscape.md","filePath":"learn/02-agent-payments/ecosystem-landscape.md","lastUpdated":1792595354000}'),r={name:"learn/02-agent-payments/ecosystem-landscape.md"};function s(i,e,c,d,l,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="a-neutral-guide-to-the-agent-payment-ecosystem" tabindex="-1">A Neutral Guide to the Agent Payment Ecosystem <a class="header-anchor" href="#a-neutral-guide-to-the-agent-payment-ecosystem" aria-label="Permalink to &quot;A Neutral Guide to the Agent Payment Ecosystem&quot;">​</a></h1><p>Agent payments are an evolving field. The protocols often discussed together solve different layers of a commercial transaction, so they are not necessarily competing replacements.</p><h2 id="classify-by-the-problem-they-solve" tabindex="-1">Classify by the problem they solve <a class="header-anchor" href="#classify-by-the-problem-they-solve" aria-label="Permalink to &quot;Classify by the problem they solve&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Question</th><th>Examples</th></tr></thead><tbody><tr><td>Tool and communication</td><td>How do agents discover tools and collaborate?</td><td>MCP, A2A</td></tr><tr><td>Commerce workflow</td><td>How does an agent find products, build a cart, and check out?</td><td>ACP, UCP</td></tr><tr><td>Authorization and trust</td><td>How can a merchant verify human intent and accountability?</td><td>AP2, card-network agent programs</td></tr><tr><td>Financial control</td><td>Should this agent pay, how much, and how should failures be handled?</td><td>AgentPay&#39;s focus</td></tr><tr><td>Payment and fulfillment</td><td>How is a machine-readable payment presented and settled?</td><td>x402 and other machine-payment protocols</td></tr></tbody></table><h2 id="protocols-at-a-glance" tabindex="-1">Protocols at a glance <a class="header-anchor" href="#protocols-at-a-glance" aria-label="Permalink to &quot;Protocols at a glance&quot;">​</a></h2><ul><li><strong>x402</strong> uses HTTP payment requirements and payment information for machine-facing services. It concerns the payment interaction; it does not by itself decide whether an agent is allowed to spend.</li><li><strong>Machine Payments Protocol (MPP)</strong> is another approach to machine-to-machine payments. Compare its current specification and supported rails with the intended integration before adopting it.</li><li><strong>AP2</strong> focuses on verifiable authorization and accountability for agent commerce, often described through signed mandates. It addresses evidence of user intent rather than every runtime budget-control problem.</li><li><strong>Visa and Mastercard agent initiatives</strong> build on existing card-network infrastructure, including identity, tokenization, and issuer controls.</li><li><strong>OpenAI/Stripe ACP and Google-led UCP</strong> address commerce workflows such as product discovery and checkout. In crypto contexts, “ACP” may also refer to an unrelated Agent Commerce Protocol; check the project and use case.</li><li><strong>MCP and A2A</strong> support tool connectivity or agent communication. They are complementary to payment and authorization mechanisms.</li></ul><p>These categories can work together in one transaction. An agent might discover a tool over a communication protocol, select an offer through a commerce flow, prove user authorization, pass a payment request through a payment protocol, and rely on a separate control layer to enforce its budget.</p><h2 id="how-agentpay-fits" tabindex="-1">How AgentPay fits <a class="header-anchor" href="#how-agentpay-fits" aria-label="Permalink to &quot;How AgentPay fits&quot;">​</a></h2><p>AgentPay focuses on the buyer-side financial control layer: identity, spending rules, budget reservation, failure recovery, and audit. It can complement a payment protocol such as x402 rather than replace its wire-level payment interaction. Protocol names, governance, and product status change quickly; verify current details against each project&#39;s official documentation before implementation.</p>',9)])])}const u=t(r,[["render",s]]);export{p as __pageData,u as default};
